import numpy as np
from scipy.special import erf
from helpers import macro_f1
gelu=lambda x: 0.5*x*(1+erf(x/np.sqrt(2)))
def fit(Phi,y,w,lam):
    T=np.eye(8)[y]-1/8
    sw=w/w.sum(); m=sw@Phi; tm=sw@T
    Pc=Phi-m; Tc=T-tm
    G=(Pc*w[:,None]).T@Pc+lam*np.eye(Phi.shape[1])
    a=np.linalg.solve(G,(Pc*w[:,None]).T@Tc)
    return a, tm-m@a+1/8
def fitk(Ztr,ytr,wtr,lam,beta=1.0):
    P=gelu(beta*Ztr@Ztr.T/768); return fit(P,ytr,wtr,lam)
def load():
    k=np.load('kernel_v3.npz'); C,yc=k['C'],k['yc']
    d3=np.load('my3_feats.npz'); d4=np.load('my4_feats.npz')
    return dict(Zp=C[:1496],yp=yc[:1496],Zm=C[1496:],ym=yc[1496:],Z3=d3['Z'],y3=d3['y'],Z4=d4['Z'],y4=d4['y'],mu=k['mu'],sd=k['sd'])
def folds(yp,s,nf=5):
    rng=np.random.default_rng(s); fo=np.zeros(len(yp),int)
    for c in range(8):
        idx=np.where(yp==c)[0]; rng.shuffle(idx); fo[idx]=np.arange(len(idx))%nf
    return fo
def run_cv(D, extra, wx, lam, seeds=(0,1,2,3), nf=5, beta=1.0):
