            else: wl=wx
            Zt=np.concatenate([Zp[tr]]+[e[0] for e in extra]); yt=np.concatenate([yp[tr]]+[e[1] for e in extra])
            wt=np.concatenate([np.ones(tr.sum())]+[np.full(len(e[1]),ww) for e,ww in zip(extra,wl)])
            a,b=fitk(Zt,yt,wt,lam,beta)
            pred[~tr]=np.argmax(gelu(beta*Zp[~tr]@Zt.T/768)@a+b,1)
        accs.append((pred==yp).mean()); f1s.append(macro_f1(yp,pred))
    return round(np.mean(accs),4), round(np.mean(f1s),4), np.round(accs,4)
